          const arm = new T3.Mesh(new T3.CapsuleGeometry(0.28, 2.6, 8, 16), BK.mat.skin(0x8d5a3b)); arm.rotation.z = Math.PI / 2 + 0.25; arm.position.set(1.5, 0.35, -0.2); g.add(arm); const mus = new T3.Mesh(new T3.SphereGeometry(0.35, 24, 16), BK.mat.muscle()); mus.scale.set(1.6, 0.8, 0.8); mus.position.set(1.6, 0.25, 0.15); g.add(mus); s.mus = mus;
