      if (c.mode === "reflex" && s.paths.length) { s.go += dt * 0.55; const L = [1.0, 0.25, 1.0], tot = 2.25; let u = s.go % 3.0, seg = 0; if (u < tot) { let acc = 0; for (seg = 0; seg < 3; seg++) { if (u < acc + L[seg]) break; acc += L[seg]; } const p = s.paths[Math.min(2, seg)].getPointAt(Math.min(1, (u - acc) / L[Math.min(2, seg)])); s.spark.position.copy(p); s.spark.visible = true; } else s.spark.visible = false; s.mus.scale.set(1.6 - 0.25 * (u > tot && u < tot + 0.4 ? 1 : 0), 0.8 + 0.25 * (u > tot && u < tot + 0.4 ? 1 : 0), 0.8); s.seg = u < 1 ? "Sensory neurone (afferent)" : u < 1.25 ? "Relay neurone in grey matter" : u < tot ? "Motor neurone (efferent)" : "Effector: muscle contracts — hand pulled away"; }
      if (c.mode === "neur" && s.paths.length) { const v = c.myelin ? 100 : 2; s.go += dt * (c.myelin ? 0.9 : 0.25); const u = s.go % 1.4; if (u < 1) { const uu = c.myelin ? Math.round(u * 10) / 10 : u; s.spark.position.copy(s.paths[0].getPointAt(Math.min(1, uu))); s.spark.visible = true; } else s.spark.visible = false; s.v = v; }
